// Generated by `just generate` from `src/plugins/claudetto-lab/slices/sandbox/domain/frontmatter.ts`. Edit the source and run `just generate`.
import {
  NO_PLUGIN_LOADED,
  NO_UNKNOWN_FIELD,
  UNKNOWN_FIELD_COUNT,
} from "../prompts.ts";

export const pluginLoaded = (text: string): boolean =>
  /Loaded inline plugin from path:/.test(text);

export const report = (
  log: string,
  text: string,
): { lines: string[]; code: number } => {
  const hits = text
    .split("\n")
    .filter((l) =>
      /unknown (?:frontmatter )?field|unrecognized field/i.test(l),
    );
  const loaded = pluginLoaded(text);
  return {
    lines: [
      `Debug log: ${log} (${text.split("\n").length} lines)`,
      ...hits,
      ...(loaded ? [] : [NO_PLUGIN_LOADED]),
      hits.length === 0
        ? NO_UNKNOWN_FIELD
        : UNKNOWN_FIELD_COUNT({ count: String(hits.length) }),
    ],
    code: hits.length === 0 && loaded ? 0 : 1,
  };
};
